 public function render_library(){if(!current_user_can('edit_posts'))wp_die(esc_html__('Permission denied.','nirmaan-builder'));$items=get_posts(array('post_type'=>'nirmaan_library','post_status'=>'publish','numberposts'=>200));?>
 <div class="wrap nirmaan-builder-admin"><h1>Library</h1><p>Reusable layouts and synchronized global elements.</p><p><button id="nirmaan-export-library" class="button">Export Library JSON</button> <label class="button">Import Library JSON <input id="nirmaan-import-library" type="file" accept="application/json,.json" hidden></label></p>
 <table class="widefat striped"><thead><tr><th>Layout</th><th>Type</th><th>Category</th><th>Actions</th></tr></thead><tbody><?php if(!$items):?><tr><td colspan="4">No saved layouts yet.</td></tr><?php endif;?><?php foreach($items as $item):?><tr><td><?php echo esc_html($item->post_title);?></td><td><?php echo get_post_meta($item->ID,'_nirmaan_global',true)?'Global Element':'Reusable Layout';?></td><td><?php echo esc_html(get_post_meta($item->ID,'_nirmaan_category',true));?></td><td><a class="button button-small" href="<?php echo esc_url(admin_url('admin.php?page=nirmaan-editor&library_id='.$item->ID));?>">Edit</a> <button class="button button-small nirmaan-delete-library" data-id="<?php echo esc_attr($item->ID);?>">Delete</button></td></tr><?php endforeach;?></tbody></table></div><?php }
 public function render_theme_builder(){if(!current_user_can('edit_theme_options'))wp_die(esc_html__('You cannot manage theme templates.','nirmaan-builder'));$templates=get_posts(array('post_type'=>'nirmaan_template','post_status'=>array('publish','draft'),'numberposts'=>100,'meta_key'=>'_nirmaan_priority','orderby'=>'meta_value_num','order'=>'DESC'));?>
 <div class="wrap nirmaan-builder-admin"><h1>Theme Builder</h1><p>Higher priority templates win when multiple templates match. Exclusion rules override inclusion rules.</p>
 <form id="nirmaan-create-template" class="nirmaan-create-template"><input name="title" required placeholder="Template name"><select name="condition"><option value="entire_site">Entire Website</option><option value="front_page">Front Page</option><option value="all_pages">All Pages</option><option value="all_posts">All Posts</option><option value="product">Single Products</option><option value="product_archive">Product Archives</option><option value="shop">Shop</option><option value="cart">Cart</option><option value="checkout">Checkout</option><option value="archive">Archives</option></select><input name="priority" type="number" value="10" min="0" max="999" aria-label="Priority"><button class="button button-primary">Create Template</button></form>
 <table class="widefat striped"><thead><tr><th>Template</th><th>Priority</th><th>Include</th><th>Exclude</th><th>Save Rules</th><th>Header</th><th>Body</th><th>Footer</th><th>Actions</th></tr></thead><tbody><?php if(!$templates):?><tr><td colspan="9">No templates yet.</td></tr><?php endif;?><?php foreach($templates as $t):$base=admin_url('admin.php?page=nirmaan-editor&template_id='.$t->ID.'&part=');$c=get_post_meta($t->ID,'_nirmaan_conditions',true);$c=is_array($c)?$c:array();$inc=array_column($c['include']??array(),'type');$inc=$inc?:array('entire_site');$exc=array_column($c['exclude']??array(),'type');?><tr><td><strong><?php echo esc_html($t->post_title);?></strong></td><td><input name="priority" type="number" min="0" max="999" value="<?php echo esc_attr(get_post_meta($t->ID,'_nirmaan_priority',true)?:10);?>" style="width:70px"></td><td><select name="include" multiple size="3" aria-label="Include conditions"><?php $this->condition_options($inc,true);?></select></td><td><select name="exclude" multiple size="3" aria-label="Exclude conditions"><?php $this->condition_options($exc,true);?></select></td><td><button class="button nirmaan-save-template-rules" data-id="<?php echo esc_attr($t->ID);?>">Save Rules</button></td><?php foreach(array('header','body','footer') as $part):?><td><a class="button button-small" href="<?php echo esc_url($base.$part);?>">Edit</a></td><?php endforeach;?><td><button class="button button-small nirmaan-delete-template" data-id="<?php echo esc_attr($t->ID);?>">Delete</button></td></tr><?php endforeach;?></tbody></table></div><?php }
 private function condition_options($selected,$multiple=false){
  $selected=is_array($selected)?$selected:array($selected);
  $options=array('entire_site'=>'Entire Website','front_page'=>'Front Page','all_pages'=>'All Pages','all_posts'=>'All Posts','product'=>'Single Products','product_archive'=>'Product Archives','shop'=>'Shop','cart'=>'Cart','checkout'=>'Checkout','archive'=>'Archives','search'=>'Search Results','404'=>'404 Page');
  foreach($options as $value=>$label){
   $selected_attr=in_array($value,$selected,true)?' selected="selected"':'';
   echo '<option value="'.esc_attr($value).'"'.$selected_attr.'>'.esc_html($label).'</option>';
  }
 }
 public function render_editor(){$post_id=absint($_GET['post_id']??0);$template_id=absint($_GET['template_id']??0);$library_id=absint($_GET['library_id']??0);if($post_id&&!current_user_can('edit_post',$post_id))wp_die(esc_html__('You cannot edit this content.','nirmaan-builder'));if($template_id&&!current_user_can('edit_theme_options'))wp_die(esc_html__('You cannot edit theme templates.','nirmaan-builder'));if($library_id&&!current_user_can('edit_posts'))wp_die(esc_html__('You cannot edit Library items.','nirmaan-builder'));if(!$post_id&&!$template_id&&!$library_id)wp_die(esc_html__('Select content or a template to edit.','nirmaan-builder'));$part=sanitize_key($_GET['part']??'body');?>
 <div class="wrap nirmaan-editor-wrap"><div class="nirmaan-editor-topbar"><a href="<?php echo esc_url(admin_url($template_id?'admin.php?page=nirmaan-theme-builder':($library_id?'admin.php?page=nirmaan-library':'edit.php')));?>" class="button">Exit</a><strong>Nirmaan Visual Builder</strong><span class="nirmaan-save-status" aria-live="polite"></span><button id="nirmaan-undo" class="button" type="button" disabled title="Undo (Ctrl+Z)">Undo</button><button id="nirmaan-redo" class="button" type="button" disabled title="Redo (Ctrl+Shift+Z)">Redo</button><div class="nirmaan-preview-controls" role="group" aria-label="Responsive preview"><button class="button button-primary" type="button" data-preview-device="desktop" aria-pressed="true" title="Desktop preview">Desktop</button><button class="button" type="button" data-preview-device="tablet" aria-pressed="false" title="Tablet preview">Tablet</button><button class="button" type="button" data-preview-device="mobile" aria-pressed="false" title="Mobile preview">Mobile</button></div><button id="nirmaan-view-toggle" class="button" type="button">Wireframe View</button><button id="nirmaan-revisions" class="button" type="button">Revisions</button><button id="nirmaan-save-library" class="button">Save to Library</button><button id="nirmaan-save" class="button button-primary">Save</button></div>
 <div class="nirmaan-editor-layout"><aside class="nirmaan-editor-sidebar"><h2>Add Elements</h2><div id="nirmaan-module-list"></div><hr><h2>Saved Layouts / Global Elements</h2><div id="nirmaan-library-list"></div><hr><h2>Layers</h2><div id="nirmaan-layers" class="nb-layers-panel" aria-label="Element layers"></div><hr><h2>Element Settings</h2><div id="nirmaan-settings">Select an element on the canvas.</div></aside><main class="nirmaan-editor-main"><div class="nirmaan-canvas-label"><?php echo esc_html($template_id?ucfirst($part).' Template Part':($library_id?'Library: '.get_the_title($library_id):get_the_title($post_id)));?></div><div id="nirmaan-canvas" class="nirmaan-canvas"></div></main></div></div><?php }
